import{e as r,ab as a,a1 as o,m as n,r as i,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [Sept]","description":"Sept 2025 updates","frontmatter":{"title":"Monthly Updates [Sept]","description":"Sept 2025 updates","date":"2025-08-31T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/sept-2025.md","filePath":"posts/sept-2025.md"}'),l={name:"posts/sept-2025.md"};function d(h,e,p,f,m,g){const t=a("Post");return o(),n("div",null,[i(t,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>FMHY.net URLs have <strong><a href="https://i.imgur.com/rNoyhHH.png" target="_blank" rel="noreferrer">been updated</a></strong> to make them look cleaner and easier to share or type.</p></li><li><p>Split AI Chatbots into <a href="https://fmhy.net/ai#official-model-sites" target="_blank" rel="noreferrer">Official Model</a>, <a href="https://fmhy.net/ai#multiple-model-sites" target="_blank" rel="noreferrer">Multi-Model</a>, and <a href="https://fmhy.net/ai#specialized-chatbots" target="_blank" rel="noreferrer">Specialized</a> to make the section easier to navigate.</p></li><li><p>Added a <a href="https://fmhy.net/internet-tools#qr-code-tools" target="_blank" rel="noreferrer">QR Code Tools</a> section to Internet.</p></li><li><p>Added an <a href="https://fmhy.net/educational#sat-testing" target="_blank" rel="noreferrer">SAT Testing</a> section to Educational.</p></li><li><p>Added an <a href="https://fmhy.net/ai#coding-ai-benchmarks" target="_blank" rel="noreferrer">AI Coding Benchmarks</a> section to AI.</p></li><li><p>Merged <a href="https://fmhy.net/readingpiracyguide#quotes-poetry" target="_blank" rel="noreferrer">Quotes / Poetry</a> into one section under Reading.</p></li><li><p>Debloated and reorganized the <a href="https://fmhy.net/text-tools#translators" target="_blank" rel="noreferrer">Translator</a> section. <a href="https://i.imgur.com/CO0U0xQ.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Debloated and reorganized the <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">Image Generator</a> section. <a href="https://i.imgur.com/wAcNMrX.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Debloated and reorganized the <a href="https://fmhy.net/system-tools#hackintosh" target="_blank" rel="noreferrer">Hackintosh</a> section. <a href="https://i.imgur.com/aAHEhqe.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Debloated and reorganized the <a href="https://fmhy.net/misc#live-webcams" target="_blank" rel="noreferrer">Live Webcams</a> section. <a href="https://i.imgur.com/jI0f3OV.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Debloated and reorganized the <a href="https://fmhy.net/miscguide#resume-portfolio" target="_blank" rel="noreferrer">Resume / Portfolio</a> section. <a href="https://i.imgur.com/pwUZsYl.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Debloated and reorganized the <a href="https://fmhy.net/text-tools#latex-tools" target="_blank" rel="noreferrer">LaTeX Tools</a> section. <a href="https://i.imgur.com/rVzuyvF.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Cleaned up formatting in the <a href="https://fmhy.net/ai#guides-tools" target="_blank" rel="noreferrer">Image Gen Guide</a> section. <a href="https://i.imgur.com/ml6JGy7.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p><strong>Thank you to CY83R, AnarchyDr, Kiri, Hugo, and anyone else who helped organize or create sections this month.</strong></p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Re-starred <a href="https://fmhy.net/ai#official-model-sites" target="_blank" rel="noreferrer">Copilot</a> in Official Models and moved it to the #2 spot. It now has unlimited o4-mini and GPT-5 access.</p></li><li><p>Starred <a href="https://fmhy.net/text-tools#translators" target="_blank" rel="noreferrer">DeepL</a> in Translators. Fast, accurate, and features flexible post-processing, making it ideal for production environments.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#download-games" target="_blank" rel="noreferrer">UnionCrax</a> in Game Downloading. Features fast hosts, pre-installs, and allows for requests.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#youtube-customization" target="_blank" rel="noreferrer">VORAPIS</a> in YouTube Customization. Restores the classic layout and improves performance.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#wii-u-wii-homebrew" target="_blank" rel="noreferrer">WiiLink</a> in Wii Homebrew. Restores functionality to Wii Channels that have been abandoned by Nintendo.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#modded-apks" target="_blank" rel="noreferrer">AN1</a> in Android APKs. Features a large library of games, quick updates, and single-click downloads.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-audio-players" target="_blank" rel="noreferrer">Namida</a> in Android Audio Players. Smooth, highly customizable, includes YouTube support, and features a nice UI.</p></li><li><p>Starred <a href="https://fmhy.net/system-tools#system-tweaks" target="_blank" rel="noreferrer">StartAllBack</a> in System Tweaks. Restores Win10-style UI features in Win11 and improves overall responsiveness.</p></li><li><p>Starred <a href="https://fmhy.net/ai" target="_blank" rel="noreferrer">Z.ai</a> in AI Chatbots. Fast, unlimited, and performs well; it&#39;s one of the better open-source reasoning models available.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#browser-emulators" target="_blank" rel="noreferrer">GAM.ONL</a> in Browser Emulators. Features a very nice UI and navigation system plus many consoles and games.</p></li><li><p>Starred the <a href="https://fmhy.net/gaming-tools#playstation-homebrew" target="_blank" rel="noreferrer">Vita Hacks Guide</a> in PlayStation Homebrew. Well-respected, easy to follow, and highly recommended for anyone starting Vita modding.</p></li><li><p>Starred <a href="https://fmhy.net/video#subtitle-tools" target="_blank" rel="noreferrer">Subtitle Edit</a> in Subtitle Tools. An easy-to-use, feature-rich, and well-maintained subtitle editor.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li>Unstarred ChatGPT; it currently has poor overall limits and reasoning quotas. It is no longer considered a top-tier free option compared to others.</li></ul>',9))])}const b=r(l,[["render",d]]);export{u as __pageData,b as default};
